import threading

class Estadisticas:
    def __init__(self):
        self.candado = threading.Lock()
        self.total = 0

    def sumar(self):
        with self.candado:
            self.total += 1

    def cerrar(self):
        with self.candado:
            self.sumar()

estadisticas = Estadisticas()
estadisticas.cerrar()

